using BARANG.Core.Api.Errors;using BARANG.Core.Application.Logistics;using BARANG.Core.Domain.Common;using BARANG.Core.Domain.Security;
namespace BARANG.Core.Api.Logistics;
public static class LogisticsEndpoints{public static IEndpointRouteBuilder MapLogisticsEndpoints(this IEndpointRouteBuilder e){RouteGroupBuilder r=e.MapGroup("/api/v1/logistics");r.MapPost("/packages",async(CreatePackageCommand c,ILogisticsAdministration s,CancellationToken ct)=>Map(await s.CreatePackageAsync(c,ct),true)).RequireAuthorization(SecurityPermissions.PackagingManage);r.MapGet("/packages/{id:guid}",async(Guid id,ILogisticsAdministration s,CancellationToken ct)=>Map(await s.GetPackageAsync(id,ct))).RequireAuthorization(SecurityPermissions.LogisticsRead);r.MapPost("/packages/{id:guid}/items",async(Guid id,AddPackageItemCommand c,ILogisticsAdministration s,CancellationToken ct)=>Map(await s.AddItemAsync(id,c,ct))).RequireAuthorization(SecurityPermissions.PackagingManage);r.MapPost("/packages/{id:guid}/complete",async(Guid id,LogisticsVersionCommand c,ILogisticsAdministration s,CancellationToken ct)=>Map(await s.CompletePackageAsync(id,c.Version,ct))).RequireAuthorization(SecurityPermissions.PackagingManage);r.MapPost("/packages/{id:guid}/handoff",async(Guid id,CreateHandoffCommand c,ILogisticsAdministration s,CancellationToken ct)=>Map(await s.ReceiveHandoffAsync(id,c,ct),true)).RequireAuthorization(SecurityPermissions.ShippingManage);r.MapPost("/handoffs/{id:guid}/release",async(Guid id,ReleaseHandoffCommand c,ILogisticsAdministration s,CancellationToken ct)=>Map(await s.ReleaseHandoffAsync(id,c,ct))).RequireAuthorization(SecurityPermissions.ShippingManage);r.MapPost("/shipments",async(CreateShipmentCommand c,ILogisticsAdministration s,CancellationToken ct)=>Map(await s.CreateShipmentAsync(c,ct),true)).RequireAuthorization(SecurityPermissions.ShippingManage);r.MapGet("/shipments/{id:guid}",async(Guid id,ILogisticsAdministration s,CancellationToken ct)=>Map(await s.GetShipmentAsync(id,ct))).RequireAuthorization(SecurityPermissions.LogisticsRead);r.MapPut("/shipments/{id:guid}/tracking",async(Guid id,RegisterTrackingCommand c,ILogisticsAdministration s,CancellationToken ct)=>Map(await s.RegisterTrackingAsync(id,c,ct))).RequireAuthorization(SecurityPermissions.ShippingManage);r.MapPost("/shipments/{id:guid}/ship",async(Guid id,LogisticsVersionCommand c,ILogisticsAdministration s,CancellationToken ct)=>Map(await s.MarkShippedAsync(id,c.Version,ct))).RequireAuthorization(SecurityPermissions.ShippingManage);r.MapPost("/shipments/{id:guid}/in-transit",async(Guid id,LogisticsVersionCommand c,ILogisticsAdministration s,CancellationToken ct)=>Map(await s.MarkInTransitAsync(id,c.Version,ct))).RequireAuthorization(SecurityPermissions.ShippingManage);r.MapPost("/shipments/{id:guid}/deliver",async(Guid id,LogisticsVersionCommand c,ILogisticsAdministration s,CancellationToken ct)=>Map(await s.ConfirmDeliveryAsync(id,c.Version,ct))).RequireAuthorization(SecurityPermissions.DeliveryManage);r.MapPost("/shipments/{id:guid}/failed-delivery",async(Guid id,LogisticsReasonCommand c,ILogisticsAdministration s,CancellationToken ct)=>Map(await s.FailDeliveryAsync(id,c,ct))).RequireAuthorization(SecurityPermissions.DeliveryManage);r.MapPost("/shipments/{id:guid}/return",async(Guid id,ReturnShipmentCommand c,ILogisticsAdministration s,CancellationToken ct)=>Map(await s.ReturnAsync(id,c,ct))).RequireAuthorization(SecurityPermissions.DeliveryManage);r.MapGet("/shipments/{id:guid}/history",async(Guid id,ILogisticsAdministration s,CancellationToken ct)=>Map(await s.HistoryAsync(id,ct))).RequireAuthorization(SecurityPermissions.LogisticsRead);return e;}private static IResult Map<T>(Result<T>r,bool created=false)=>r.IsSuccess?Results.Json(r.Value,statusCode:created?201:200):Results.Problem(ApiProblemDetailsMapper.Create(r.Error,"logistics",null));}
